content:
{
  "promos": [
    {
      "title": "A Wedding Invitation and a Death Sentence",
      "start_block": "B004",
      "end_block": "B018",
      "hook": "Rupert coldly declares 'Every important family in the county should witness it' as he and Catherine stand over a stack of wax-sealed wedding invitations.",
      "cliffhanger": "Catherine spitefully orders 'Especially to the Ashcrofts' and Rupert commands 'Send the invitations' — the viewer doesn't yet know what the Ashcrofts will do when they learn Juliana is to be executed.",
      "why": "It establishes the villainous conspiracy, the wedding, and the execution threat in under 30 seconds with zero setup needed.",
      "context_gap": "A stranger wouldn't know who Juliana is or why the Ashcrofts matter."
    },
    {
      "title": "Juliana's Defiance in the Dungeon",
      "start_block": "B054",
      "end_block": "B063",
      "hook": "A tear-stained, starving Juliana whispers 'They think hunger will make me surrender' before her eyes snap open with blazing defiance.",
      "cliffhanger": "Juliana grips the iron ring and declares 'They cannot take who I am!' — the viewer is left wondering if she will survive long enough for rescue.",
      "why": "It's a raw, emotional underdog moment that makes viewers root for Juliana and need to see her escape.",
      "context_gap": "A stranger wouldn't know why she's imprisoned or who 'they' are."
    },
    {
      "title": "A Warning to Every Woman",
      "start_block": "B042",
      "end_block": "B048",
      "hook": "Clarissa's voice turns chilling as she says 'Not just an execution. A warning.'",
      "cliffhanger": "Clarissa stares directly at the viewer and declares 'Juliana's ruin will be a lesson. And we will be there to watch' — the threat hangs unresolved.",
      "why": "The direct address to camera and cruel aristocratic smugness create an immediate villain the audience loves to hate.",
      "context_gap": "A stranger wouldn't know Clarissa is Juliana's sister or the history of their rivalry."
    }
  ],
  "moments": [
    {
      "start_block": "B012",
      "end_block": "B014",
      "kind": "hook",
      "description": "Rupert vows 'no one will question what happened to the woman who tried to stop us' and Catherine confirms 'Juliana's execution comes after the wedding.'"
    },
    {
      "start_block": "B036",
      "end_block": "B038",
      "kind": "reveal",
      "description": "Clarissa's husband reads the invitation aloud: 'The sentencing of the condemned' as Clarissa laughs with dark delight."
    },
    {
      "start_block": "B046",
      "end_block": "B048",
      "kind": "cliffhanger",
      "description": "Clarissa declares Juliana's ruin will be a lesson 'to every woman who thinks she can rise above the place she was given' and stares directly at the viewer."
    },
    {
      "start_block": "B055",
      "end_block": "B063",
      "kind": "emotional",
      "description": "Juliana's eyes snap open with defiance as she drags herself upright and declares 'They cannot take who I am!'"
    }
  ]
}
